package com.styleshop.product.model;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false) private BigDecimal price; @Column(length=2000) private String description; private String imageUrl; private String productUrl; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="category_id") private Category category; public Long getId(){return id;} public void setId(Long v){id=v;} public String getName(){return name;} public void setName(String v){name=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public String getProductUrl(){return productUrl;} public void setProductUrl(String v){productUrl=v;} public Category getCategory(){return category;} public void setCategory(Category v){category=v;} }
